// Lane Init: the GetLeads lane of Enrich Contacts. One run per launch over the WHOLE company
// list; the lane worries about itself: it walks the list in chunks of 500 companies (the
// size this vendor's API and pacing want), asks the vendor per chunk, and hands each chunk's people
// to the writer helper. The Rootflow only orchestrates. The input item is the Rootflow's contract:
// { base, peopleTableId, companiesTableId, peopleFields, contactSourceMulti, dncDomains,
//   companies:[{recordId, domain, company, band, cap, floor}], parentExecId, clientRecId }.
const inp=$input.first().json||{};
const who='Enrich Contacts GetLeads lane';
if(!/^app[A-Za-z0-9]{14}$/.test(String(inp.base||''))) throw new Error(who+' was called without a valid base.');
if(!inp.peopleTableId) throw new Error(who+' was called without peopleTableId.');
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const sd=$getWorkflowStaticData('global');
sd.lane={ execId:String($execution.id), startedAt:new Date().toISOString(), chunks:0, called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', skipped:'', built:0, updated:0, heldUnchanged:0, dupes:0, noKey:0, fenced:0, emailsAppended:0, dnc:0, written:0, updatedWritten:0, writeErrors:0, writeReasons:[], coveredDomains:{}, singleSelectSource:false, companiesIn:companies.length };
const CHUNK=500;
const out=[];
for(let i=0;i<companies.length;i+=CHUNK){ out.push({ json:{ idx:out.length+1, count:Math.ceil(companies.length/CHUNK), companies:companies.slice(i,i+CHUNK) } }); }
if(!out.length) return [{ json:{ _empty:true, idx:0, count:0, companies:[] } }];
return out;

// GL Requests: the GetLeads provider of Enrich Contacts. Input: the batch plan, one item
// { companies:[{recordId, domain, company, band, cap, floor}] }. Output: one item per
// POST /api/v1/contacts/search call, or one {_none:true} when there is nothing to ask.
//
// The floor is expressed in GetLeads' own six levels (C-Team, VP, Director, Manager, Staff, Other;
// pulled live 2026-09-08). "Everyone non-junior": Staff (individual contributors) rides along
// only at small companies, Other (unknown) always rides (unknown is not junior). No department
// filter: every function is asked (ruled 2026-09-08, everyone who is not junior).
//
// One call per (floor, cap) group, up to 1,000 domains a call: with max_per_company at the cap
// (GetLeads hard-stops at 50) a 100-company batch never exceeds the 5,000-row page, and the node
// still pages on next_offset for safety. Every row costs one fair-use row, never cash.
const inp=$input.first().json||{};
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const LEVELS={ wide:['C-Team','VP','Director','Manager','Staff','Other'], nonjunior:['C-Team','VP','Director','Manager','Other'], manager:['C-Team','VP','Director','Manager'] };
const COLUMNS=['First Name','Last Name','Contact Full Name','Email','Email Verification Status','Current Job Title','Seniority Level','Department / Function','Contact LinkedIn URL','Cellphone','Direct Office Phone','Company Domain','Work Email Domain','Current Employer Name'];
const groups={};
for(const c of companies){ const floor=LEVELS[c.floor]?c.floor:'wide'; const cap=Math.max(1,Math.min(50,Number(c.cap)||20)); const k=floor+':'+String(cap).padStart(2,'0'); (groups[k]=groups[k]||{ floor, cap, list:[] }).list.push(c.domain); }
const out=[];
for(const k of Object.keys(groups).sort()){
  const g=groups[k];
  for(let i=0;i<g.list.length;i+=1000){
    const part=g.list.slice(i,i+1000);
    out.push({ json:{ body:{ domains:part, seniority:LEVELS[g.floor], max_per_company:g.cap, limit:5000, offset:0, columns:COLUMNS }, domains:part, cap:g.cap, floor:g.floor } });
  }
}
if(!out.length) return [{ json:{ _none:true } }];
return out;

// GL Parse: every page GetLeads answered -> people per domain, plus the provider verdict. The one
// item out is the provider contract every Enrich Contacts provider answers with:
//   { provider, status: ok | skipped | error, reason, stats:{called, returned, kept, credits, errors,
//     firstError, failReasons[]}, people:{ <domain>: [ {source, sourceId, name, title, seniority,
//     department, email, linkedin, phone} ] } }
// It never throws. A missing credential, an exhausted fair-use budget or a dead API are a status
// on this item and a line in the caller's log; the caller moves on to the next provider (ruled
// 2026-09-08: unlimited providers, nothing blocks on one of them).
//
// Rows are matched to the plan by the row's own company domain, never by call order: the node pages
// on next_offset, so one request can answer with several items and alignment by index is not
// safe. Column names in the REST answer are the catalog's raw names; the docs say display labels on
// MCP and CSV, raw names on JSON, so every field is read through a normalized-key lookup that
// accepts either spelling.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const inp=$('GL Requests').first().json||{};
const plan=$('Chunk Loop').first().json||{};
const byDomain={}; for(const c of (Array.isArray(plan.companies)?plan.companies:[])){ if(c&&c.domain) byDomain[String(c.domain).toLowerCase()]=c; }
const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], dropped:0, pages:0 };
const people={};
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const nk=(s)=>String(s).toLowerCase().replace(/[^a-z0-9]/g,'');
const pick=(row,cands)=>{ for(const c of cands){ const v=row[c]; if(v!==undefined&&v!==null&&String(v).trim()!==''&&String(v).trim()!=='N/A') return String(v).trim(); } return ''; };
const flat=(r)=>{ const o={}; for(const k of Object.keys(r||{})){ const v=r[k]; if(v&&typeof v==='object'&&!Array.isArray(v)){ for(const k2 of Object.keys(v)) o[nk(k2)]=v[k2]; } o[nk(k)]=v; } return o; };
let items=[];
if(inp._none){ return [{ json:{ provider:'GetLeads', status:'skipped', reason:'nothing to ask', stats:st, people:{} } }]; }
try{ items=$('GL Search').all(); }catch(e){ items=[]; }
let noKey=false, budget=false;
for(const it of items){
  const j=it.json||{};
  st.pages++;
  if(j.error&&j.contacts===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ noKey=true; continue; }
    if(/fair.?use|not enough credits|credits_exhausted|payment required|\b402\b/i.test(msg)){ budget=true; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue; }
    st.errors++; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue;
  }
  if(j.ok===false||(!Array.isArray(j.contacts)&&j.message)){
    const msg=String(j.message||j.code||'answer without contacts');
    if(/fair.?use|not enough credits|credits_exhausted/i.test(msg+' '+String(j.code||''))){ budget=true; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue; }
    st.errors++; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue;
  }
  if(!Array.isArray(j.contacts)){ st.errors++; const r='GetLeads: unreadable answer '+JSON.stringify(j).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue; }
  st.credits+=Number(j.query_credits_used)||0;
  for(const raw of j.contacts){
    st.returned++;
    const r=flat(raw);
    const email=pick(r,['email','emailaddress','workemail']).toLowerCase();
    let d=norm(pick(r,['companydomain','domain','workemaildomain','emaildomain']));
    if(!d||!byDomain[d]){ const at=email.lastIndexOf('@'); const ed=at>-1?email.slice(at+1):''; if(ed&&byDomain[ed]) d=ed; }
    const c=byDomain[d];
    if(!c){ st.dropped++; continue; }
    const list=people[d]||(people[d]=[]);
    if(list.length>=(Number(c.cap)||50)) continue;
    const first=pick(r,['firstname']), last=pick(r,['lastname']);
    const name=pick(r,['contactfullname','fullname'])||((first+' '+last).trim());
    if(!name) continue;
    list.push({
      source:'GetLeads', sourceId:pick(r,['contactid','id','contactuuid','personid']),
      name:name, title:pick(r,['currentjobtitle','jobtitle','title']),
      seniority:pick(r,['senioritylevel','seniority','joblevel']), department:pick(r,['departmentfunction','jobfunction','function']),
      email:email, emailStatus:pick(r,['emailverificationstatus','emailstatus']),
      linkedin:pick(r,['contactlinkedinurl','linkedinurl','linkedin']), phone:pick(r,['cellphone','directofficephone','phone'])
    });
    st.kept++;
  }
}
try{ st.called=$('GL Requests').all().filter(i=>i.json&&!i.json._none).length; }catch(e){ st.called=st.pages; }
let status='ok', reason='';
if(noKey&&!st.kept&&!st.errors){ status='skipped'; reason='no credential on the GetLeads node'; }
else if(budget&&!st.kept){ status='skipped'; reason='fair-use budget exhausted'; }
else if(st.errors&&!st.kept&&items.length&&st.errors>=items.length){ status='error'; reason=st.firstError; }
if(budget&&st.kept) st.failReasons.push('GetLeads: fair-use budget hit mid-batch, later pages skipped');
return [{ json:{ provider:'GetLeads', status, reason, stats:st, people } }];

// Writer Input: this chunk's people (from GL Parse) plus the writer's contract, one item for the
// writer helper. An empty answer still goes through the writer (it costs one held read and returns
// zero), so the lane's counters stay honest and simple.
const ctx=$('Enrich Trigger').first().json||{};
const chunk=$('Chunk Loop').first().json||{};
let parsed={}; try{ parsed=$('GL Parse').first().json||{}; }catch(e){}
return [{ json:{ base:ctx.base, peopleTableId:ctx.peopleTableId, peopleFields:ctx.peopleFields||[], contactSourceMulti:ctx.contactSourceMulti===true, dncDomains:ctx.dncDomains||[], provider:'GetLeads', companies:chunk.companies||[], people:(parsed.people&&typeof parsed.people==='object')?parsed.people:{} } }];

// Lane Tick: adds this chunk's vendor counters (GL Parse) and writer counters (Call Writer) to the
// lane's running totals in this execution's static data (one execution, so the accumulator holds),
// then emits one unconditional tick so the loop never depends on the payload of the work.
const sd=$getWorkflowStaticData('global'); const a=sd.lane;
const n=(v)=>Number(v)||0;
let p={}; try{ p=$('GL Parse').first().json||{}; }catch(e){}
const s=p.stats||{};
a.chunks++; a.called+=n(s.called); a.returned+=n(s.returned); a.kept+=n(s.kept); a.credits+=n(s.credits); a.errors+=n(s.errors);
if(!a.firstError&&s.firstError) a.firstError=String(s.firstError).slice(0,200);
if(p.status==='skipped'&&p.reason&&p.reason!=='nothing to ask') a.skipped=String(p.reason);
if(p.status==='error'&&!a.firstError) a.firstError=String(p.reason||'').slice(0,200);
let w={}; try{ w=$('Call Writer').first().json||{}; }catch(e){}
if(w.error&&w.written===undefined){ a.writeErrors+=1; if(a.writeReasons.length<5) a.writeReasons.push('writer crashed: '+String((w.error&&w.error.message)||w.error).slice(0,160)); }
else { for(const k of ['built','updated','heldUnchanged','dupes','noKey','fenced','emailsAppended','dnc','written','updatedWritten','writeErrors']) a[k]+=n(w[k]); if(w.singleSelectSource) a.singleSelectSource=true; for(const r of (w.writeReasons||[])){ if(a.writeReasons.length<5&&a.writeReasons.indexOf(r)<0) a.writeReasons.push(r); } for(const d of (w.coveredDomains||[])) a.coveredDomains[d]=1; }
return [{ json:{ tick:true, chunk:a.chunks } }];

// Lane Log: the lane's own Hub row, keyed "<parent execution>-getleads", Automation
// "Enrich Contacts GetLeads", Client attached. Status computed: a skipped lane (no credential,
// out of credits, nothing to ask) is Succeeded with a Skipped line; vendor errors and refused
// writes count as errors; Failed only when every call failed and nothing was written.
const ctx=$('Enrich Trigger').first().json||{};
const a=$getWorkflowStaticData('global').lane||{};
const n=(v)=>Number(v)||0;
const covered=Object.keys(a.coveredDomains||{}).length;
const failed=n(a.errors)+n(a.writeErrors);
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(a.startedAt).getTime())/1000)); }catch(e){}
const allFailed=n(a.called)>0&&n(a.errors)>=n(a.called)&&!n(a.written);
const lines=[
  '**GetLeads: '+n(a.companiesIn)+' companies asked in '+n(a.chunks)+' chunk'+(n(a.chunks)===1?'':'s')+', '+n(a.returned)+' people returned, '+n(a.built)+' new, '+n(a.updated)+' held filled, '+n(a.written)+' rows written**',
  '', '**Parent run:** '+(ctx.parentExecId||'?')+' (this row is the GetLeads lane of it)',
  '', '- **Vendor:** called '+n(a.called)+', returned '+n(a.returned)+', kept '+n(a.kept)+(n(a.credits)?', credits '+(Math.round(n(a.credits)*100)/100):'')+(n(a.errors)?', errors '+n(a.errors)+(a.firstError?' ('+a.firstError+')':''):''),
  '- **Merge:** '+n(a.built)+' new rows; '+n(a.updated)+' held rows filled ('+n(a.emailsAppended)+' emails appended); '+n(a.heldUnchanged)+' held unchanged; '+n(a.dupes)+' same-person merges; '+n(a.noKey)+' without a usable first name; '+n(a.fenced)+' LinkedIn URLs rejected by the name fence; '+n(a.dnc)+' on the DNC list',
  '- **Written (confirmed by Airtable):** '+n(a.written)+' ('+n(a.updatedWritten)+' updates of held rows)'+(n(a.writeErrors)?', '+n(a.writeErrors)+' refused':''),
  '- **Companies with at least one person after this lane:** '+covered
];
if(a.singleSelectSource) lines.push('- **Contact Source is a single select on this base:** only the first source per person was recorded');
if(a.skipped) lines.push('', '**Skipped ('+a.skipped+')**');
if((a.writeReasons||[]).length){ lines.push('', '**Write failures**'); for(const r of a.writeReasons) lines.push('- '+r); }
const log={ 'Execution ID':(ctx.parentExecId||String($execution.id))+'-getleads', 'Automation':'Enrich Contacts GetLeads', 'Status':allFailed?'Failed':(failed?'Succeeded with errors':'Succeeded'), 'Trigger':'event', 'Errors':failed, 'Run at':a.startedAt, 'Target':'People ('+(ctx.peopleTableId||'')+')', 'Records In':n(a.companiesIn), 'Records Out':n(a.written), 'Duration s':dur, 'Description':lines.join('\n'), 'Tally':JSON.stringify(Object.assign({}, a, { coveredDomains:covered })), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id };
if(ctx.clientRecId) log['Client']=[ctx.clientRecId];
return [{ json:log }];

// Lane Response: the last node, what the Rootflow receives from this lane: counters only.
const a=$getWorkflowStaticData('global').lane||{};
const covered=Object.keys(a.coveredDomains||{});
return [{ json:{ provider:'GetLeads', status:a.skipped?'skipped':((a.called&&a.errors>=a.called&&!a.written)?'error':'ok'), reason:a.skipped||a.firstError||'', chunks:a.chunks, called:a.called, returned:a.returned, kept:a.kept, credits:a.credits, errors:a.errors, built:a.built, updated:a.updated, dupes:a.dupes, fenced:a.fenced, emailsAppended:a.emailsAppended, dnc:a.dnc, written:a.written, writeErrors:a.writeErrors, singleSelectSource:!!a.singleSelectSource, coveredDomains:covered } }];
